import{_ as i}from"./Neien2-a6a032a1.js";import{i as f,j as d,o as r,c as o,a,u as c,p as u,q as l,s as v,_ as p}from"./index-b2439765.js";const m="/DungeonOfAsunVue/assets/white_dragon-73d20ab5.png",h="/DungeonOfAsunVue/assets/Lorus-a56f7d1b.png",b="/DungeonOfAsunVue/assets/dwarf-fa8ea496.png",g="/DungeonOfAsunVue/assets/humans-a1635e8e.png",n=e=>(l("data-v-8fff1c28"),e=e(),v(),e),_={class:"visible"},x=u('<div class="header" data-v-8fff1c28><h1 data-v-8fff1c28>L&#39;Histoire générale</h1><h2 data-v-8fff1c28>L&#39;Aube d&#39;Asun : Une Épopée à travers les<span data-v-8fff1c28> Âges </span></h2></div><div class="row" data-v-8fff1c28><article data-v-8fff1c28><div class="title-section" data-v-8fff1c28><h2 data-v-8fff1c28>La genèse</h2><h3 data-v-8fff1c28>Introduction</h3></div><p data-v-8fff1c28> Au commencement, il n&#39;y avait que le Néant, un vide infini habité par des entités éternelles connues sous le nom d&#39;<span data-v-8fff1c28>Êtres du Néant</span>. Parmi eux, un être singulier ressentit le besoin de créer, de façonner quelque chose de nouveau. Ce fut <span data-v-8fff1c28>Riannedos</span>, le dragon primordial, qui, par un acte de volonté divine, enveloppa son propre corps pour donner naissance à un monde. Ainsi naquit <span data-v-8fff1c28>Asun</span>, un berceau façonné par le Temps et protégé par les écailles cosmiques de son créateur.<br data-v-8fff1c28><br data-v-8fff1c28> Riannedos n&#39;était pas seul longtemps. D&#39;autres Êtres du Néant vinrent à lui, fascinés par sa création. <span data-v-8fff1c28>Quaara</span>, déesse de la nature, et son frère <span data-v-8fff1c28>Gusius</span>, dieu des animaux, insufflèrent la vie dans ce monde, donnant naissance à des forêts luxuriantes, des créatures majestueuses, et des océans sans fin.<br data-v-8fff1c28><br data-v-8fff1c28><span data-v-8fff1c28>Eone</span>, dieu des savoirs, offrit la connaissance aux premiers habitants : les Dragons. Ces derniers régnèrent en maîtres sur Asun, forts de leur sagesse et de leur puissance. Mais la vie éternelle s&#39;avéra être un fardeau. C&#39;est alors qu&#39;intervint <span data-v-8fff1c28>Fauscht</span>, dieu de la mort, qui offrit aux dragons le don de la mortalité, libérant ainsi leur essence de l&#39;ennui de l&#39;éternité.<br data-v-8fff1c28><br data-v-8fff1c28> Enfin, <span data-v-8fff1c28>Théomis</span>, dieu de l&#39;ordre, descendit avec ses enfants pour façonner les <span data-v-8fff1c28>Hommes</span>, destinés à vivre sous la domination des Dragons, afin d&#39;apprendre et de prospérer sous leur tutelle divine. </p></article><div class="image" data-v-8fff1c28><img src="'+m+'" data-v-8fff1c28><div class="filter" data-v-8fff1c28></div></div></div><div class="row-reverse" data-v-8fff1c28><article data-v-8fff1c28><div class="title-section" data-v-8fff1c28><h2 data-v-8fff1c28>L&#39;ère des Hommes</h2><h3 data-v-8fff1c28>Royaume Saint de Lorus</h3></div><p data-v-8fff1c28> Le fragile équilibre fut rompu lorsque Théomis confia à son fils, <span data-v-8fff1c28>Edes</span>, la mission de protéger les Hommes. Animé par une soif de justice intransigeante, Edes mena une croisade impitoyable contre les Dragons, les décimant presque jusqu&#39;à leur extinction. Seuls quelques survivants se mêlèrent aux hommes, donnant naissance aux <span data-v-8fff1c28>Drakèides</span>, héritiers d&#39;un sang mêlé de gloire et de malédiction.<br data-v-8fff1c28><br data-v-8fff1c28> Après sa victoire, Edes fonda le <span data-v-8fff1c28>Royaume Saint de Lorus</span>, un empire théocratique où l&#39;homme dominait, glorifiant Théomis et Edes comme des divinités suprêmes. Ce royaume devint le symbole de la puissance humaine, mais aussi de l&#39;arrogance des mortels face aux autres races bénies par les dieux.<br data-v-8fff1c28><br data-v-8fff1c28> La politique expansionniste et belliqueuse de Lorus entraîna la naissance de nouveaux royaumes : <span data-v-8fff1c28>L&#39;Empire de Koven</span>, dominé par des orcs, ennemis jurés de Lorus. <span data-v-8fff1c28>Le Royaume de Trésabia</span>, havre de paix et de diplomatie. <span data-v-8fff1c28>La Dynastie Owrilia</span>, issue de l&#39;union des dragons survivants et des habitants pacifistes de Trésabia, fondée sur des principes d&#39;équilibre et de coexistence. </p></article><div class="image-left" data-v-8fff1c28><img src="'+h+'" data-v-8fff1c28><div class="filter-left" data-v-8fff1c28></div></div></div><div class="row" data-v-8fff1c28><article data-v-8fff1c28><div class="title-section" data-v-8fff1c28><h2 data-v-8fff1c28>Le nouveau Monde</h2><h3 data-v-8fff1c28>Exploration Millénaire</h3></div><p data-v-8fff1c28> Au-delà des frontières connues d&#39;Asun s&#39;étend un territoire inexploré, appelé le <span data-v-8fff1c28>Nouveau Monde</span>. Pendant des millénaires, des peuples divers s&#39;y aventurèrent, cherchant richesse, savoir, et rédemption. Ce fut un terrain d&#39;expansion, mais aussi de conflits, car les vieilles croyances s&#39;effritaient. De nouveaux dieux, de nouvelles races, et de nouveaux empires virent le jour.<br data-v-8fff1c28><br data-v-8fff1c28> C&#39;est dans ce chaos qu&#39;apparurent les <span data-v-8fff1c28>Vampires</span>, êtres du Void, avatars de vengeance contre Théomis et sa lignée. Rejetant les doctrines du Royaume Saint de Lorus, ils cherchèrent à corrompre l&#39;œuvre des dieux et à renverser l&#39;ordre établi. </p></article><div class="image" data-v-8fff1c28><img src="'+b+'" data-v-8fff1c28><div class="filter" data-v-8fff1c28></div></div></div><div class="row-reverse" data-v-8fff1c28><article data-v-8fff1c28><div class="title-section" data-v-8fff1c28><h2 data-v-8fff1c28>L&#39;Empire</h2><h3 data-v-8fff1c28>Montée de l&#39;Empire</h3></div><p data-v-8fff1c28> Sur ce continent fracturé, un homme parvint à unir des peuples disparates sous une seule bannière : <span data-v-8fff1c28>l&#39;Empire Cytanique</span>. Bien qu&#39;il n&#39;ait jamais dominé la totalité du monde, il s&#39;imposa comme la plus grande force militaire, culturelle, et politique d&#39;Asun. Il établit des cités prospères, des routes commerciales florissantes, et des institutions stables, surpassant même la puissance du Saint Royaume de Lorus.<br data-v-8fff1c28><br data-v-8fff1c28> Cependant, l&#39;ombre d&#39;un ancien pouvoir plane encore sur Asun... </p></article><div class="image-left" data-v-8fff1c28><img src="'+g+'" data-v-8fff1c28><div class="filter-left" data-v-8fff1c28></div></div></div><div class="row" data-v-8fff1c28><article data-v-8fff1c28><div class="title-section" data-v-8fff1c28><h2 data-v-8fff1c28>Le secret millénaires</h2><h3 data-v-8fff1c28>Reliques de Neien</h3></div><p data-v-8fff1c28> Parmi tous les dieux, <span data-v-8fff1c28>Neien</span> fut le plus puissant. Anciennement dieu de la miséricorde, il fut trahi, banni, et enfermé par ses pairs au fin fond du <span data-v-8fff1c28>Donjon d&#39;Asun</span>, connu sous le nom des <span data-v-8fff1c28>Enfers</span>. Son essence fut fracturée et dispersée à travers Asun sous forme de <span data-v-8fff1c28>Reliques</span>.<br data-v-8fff1c28><br data-v-8fff1c28> Ces artefacts, imprégnés de fragments de sa divinité, offrent à quiconque les détient un pouvoir égal à celui d’un dieu. Leur influence est un appel irrésistible pour les aventuriers, les rois, et même les dieux eux-mêmes.<br data-v-8fff1c28><br data-v-8fff1c28> L&#39;histoire d&#39;Asun est celle d&#39;un monde façonné par des dieux, mais peut-être, un jour, sera-t-il façonné par des mortels.<br data-v-8fff1c28><br data-v-8fff1c28><i data-v-8fff1c28>Bienvenue dans le monde d&#39;Asun, où chaque choix peut façonner le destin des dieux et des hommes.</i></p></article><div class="image" data-v-8fff1c28><img src="'+i+'" data-v-8fff1c28><div class="filter" data-v-8fff1c28></div></div></div>',6),q={class:"banner"},A=n(()=>a("h3",null,"Ecrivez l'histoire",-1)),L=n(()=>a("div",{class:"banner-img"},null,-1)),y=f({__name:"StoryView",setup(e){const t=d();return(E,s)=>(r(),o("div",_,[x,a("div",q,[A,a("button",{onClick:s[0]||(s[0]=S=>c(t).push({path:"/Rules/creation"}))},"Commencer"),L])]))}});const D=p(y,[["__scopeId","data-v-8fff1c28"]]);export{D as default};
